    icols={v for v,_ in objs}
    for nc,newpos in fc.items():
        if nc in icols: continue
        # find fragment neighbor cell(s) whose color exists as inside object, orthogonally adjacent OR dominant-axis-displacement
        best=None
        for ac in icols:
            if ac not in fc: continue
            dr=sum(r for r,c in newpos)/len(newpos)-sum(r for r,c in fc[ac])/len(fc[ac])
            dc=sum(c for r,c in newpos)/len(newpos)-sum(c for r,c in fc[ac])/len(fc[ac])
            # unit direction sign
            sr=int(dr/abs(dr)) if abs(dr)>1e-9 else 0
            sc=int(dc/abs(dc)) if abs(dc)>1e-9 else 0
            if (sr,sc)==(0,0) or (abs(dr)+abs(dc))!=2*(abs(sr)*abs(dr)+abs(sc)*abs(dc))//1:
                pass
            score=0
            if sr: score+=abs(dr)
            if sc: score+=abs(dc)
            if score>1: continue   # reject strong diagonal; prefer axis-aligned displacement
            if best is None or (dr,dc)<(best[0],best[1]): best=((dr,dc),ac,sr,sc)
        if best is None: continue
        _,ac,sr,sc=best
        # anchor object
        av,a_comp=[o for o in objs if o[0]==ac][0]
        yr=min(r for r,_ in a_comp); xc=min(c for _,c in a_comp)
        bh=max(r for r,_ in a_comp)-yr+1; bw=max(c for _,c in a_comp)-xc+1
        # direction: new cell was displaced FROM anchor by (dr,dc); mirror so new block goes opposite side (away from fragment relation? demo1: 9 left of 3 -> 99 left of 3: direction of new relative to anchor in frag = sign placed)
        dsign_r = int(round(dr*sr)) if sr else 0
        dsign_c = int(round(dc*sc)) if sc else 0
        # actually new block goes in direction of (dsign) from anchor block? demo1: frag delta 9->3 was (0,+1) meaning 9 LEFT of 3; output 9s LEFT of 3-block: offset from anchor = -(direction from anchor to new) -> 9 is on side opposite? no: 9 is left of 3 in BOTH. direction from anchor TO new in frag = (0,-1); place new block at anchor_block_offset += (dir*n*size)...
        oy,ox=(yr-dsign_r*bh, xc-dsign_c*bw)
        # if we used anchor mean, dsign already = new_pos_mean - anchor_mean. placing at oy,ox shifts whole block toward new position direction? we want new block on the SAME side as the fragment relation. Since fragment relation IS new pos minus anchor pos, the offset should be applied directly: place new block starting at anchor block edge shifted by one block step in direction of relation:
        drr = 1 if dsign_r>0 else (-1 if dsign_r<0 else 0)
        dcc = 1 if dsign_c>0 else (-1 if dsign_c<0 else 0)
        oy = yr + drr*bh; ox = xc + dcc*bw
        for i in range(bh):
            for j in range(bw):
                ny_,nx_=oy+i, ox+j
                if 0<=ny_<H and 0<=nx_<W and box[ny_][nx_]==bg:
