                r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
                if all((r==r0 or r==r1) and (i==c0 or i==c1) for r,i in pts):
                    corner=c; box=(r0,r1,c0,c1)
    r0,r1,c0,c1=box
    out=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
